-- POSE CRM Task 1 GUI import for PostgreSQL 18.
-- Execute only once against the original V2 baseline in pose_crm_v2.
-- This self-contained script has no psql meta commands or server-side CSV paths.
-- It inserts only the 35/202/202/392 Task 1 rows and contains no reset operation.

BEGIN;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';

-- Fail closed unless this is the exact pre-Task-1 V2 baseline.
DO $$
DECLARE
    actual_count integer;
BEGIN
    IF current_database() <> 'pose_crm_v2' THEN
        RAISE EXCEPTION 'Task 1 import aborted: connected database is %, expected pose_crm_v2.', current_database();
    END IF;
    IF current_setting('server_encoding') <> 'UTF8' THEN
        RAISE EXCEPTION 'Task 1 import aborted: server encoding is %, expected UTF8.', current_setting('server_encoding');
    END IF;
    SELECT count(*) INTO actual_count FROM organizations; IF actual_count <> 6 THEN RAISE EXCEPTION 'Pre-import organizations expected 6, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM users; IF actual_count <> 36 THEN RAISE EXCEPTION 'Pre-import users expected 36, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM offering_categories; IF actual_count <> 12 THEN RAISE EXCEPTION 'Pre-import offering_categories expected 12, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM offerings; IF actual_count <> 26 THEN RAISE EXCEPTION 'Pre-import offerings expected 26, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM offering_prices; IF actual_count <> 24 THEN RAISE EXCEPTION 'Pre-import offering_prices expected 24, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM sales_assignments; IF actual_count <> 49 THEN RAISE EXCEPTION 'Pre-import sales_assignments expected 49, actual %', actual_count; END IF;
    IF NOT EXISTS (SELECT 1 FROM offering_categories WHERE id='d0b6dc82-f87d-505d-88c5-7f7dfa73acf1' AND code='WAREHOUSING') THEN
        RAISE EXCEPTION 'Pre-import LOG/WAREHOUSING baseline category is missing.';
    END IF;
END $$;

