-- Final counts and core Task 1 relationship checks before commit.
DO $$
DECLARE
    actual_count integer;
    violations integer;
BEGIN
    SELECT count(*) INTO actual_count FROM offering_categories; IF actual_count <> 47 THEN RAISE EXCEPTION 'Post-import offering_categories expected 47, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM offerings; IF actual_count <> 228 THEN RAISE EXCEPTION 'Post-import offerings expected 228, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM offering_prices; IF actual_count <> 226 THEN RAISE EXCEPTION 'Post-import offering_prices expected 226, actual %', actual_count; END IF;
    SELECT count(*) INTO actual_count FROM sales_assignments; IF actual_count <> 441 THEN RAISE EXCEPTION 'Post-import sales_assignments expected 441, actual %', actual_count; END IF;
    SELECT count(*) INTO violations FROM offerings o JOIN offering_categories c ON c.id=o.category_id WHERE o.organization_id<>c.organization_id; IF violations<>0 THEN RAISE EXCEPTION 'Offering/category organization-scope violations: %', violations; END IF;
    SELECT count(*) INTO violations FROM offering_prices p JOIN offerings o ON o.id=p.offering_id WHERE p.organization_id<>o.organization_id OR p.amount<=0 OR p.currency_code<>'VND' OR p.pricing_unit<>o.unit; IF violations<>0 THEN RAISE EXCEPTION 'Task 1 price violations: %', violations; END IF;
    SELECT count(*) INTO violations FROM sales_assignments a JOIN offerings o ON o.id=a.offering_id JOIN users s ON s.id=a.sales_user_id JOIN users m ON m.id=a.assigned_by_user_id WHERE a.organization_id<>o.organization_id OR a.organization_id<>s.organization_id OR a.organization_id<>m.organization_id; IF violations<>0 THEN RAISE EXCEPTION 'Task 1 assignment organization-scope violations: %', violations; END IF;
END $$;

COMMIT;

-- Run verify_task1_gui.sql after this transaction commits successfully.
